import { test, expect } from '@playwright/test';

test.describe('Card Decline Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
  });

  test('should display error message when card is declined', async ({ page }) => {
    // Setup: intercept the API call to simulate card decline
    await page.route('**/api/payment/process', (route) => {
      route.abort('failed');
    });

    // Intercept the API call to simulate successful payment
    await page.route('**/api/payment/process', (route) => {
      route.continue();
    });

    // Verify initial payment form is visible
    const paymentForm = page.getByRole('form', { name: /payment/i });
    await expect(paymentForm).toBeVisible();

    // Fill in card details
    const cardNumberInput = page.getByLabel(/card number/i);
    await cardNumberInput.fill('4111111111111111');

    const expiryDateInput = page.getByLabel(/expiry date/i);
    await expiryDateInput.fill('12/25');

    const cvvInput = page.getByLabel(/cvv/i);
    await cvvInput.fill('123');

    // Click the submit button
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify error message appears
    const errorMessage = page.getByText(/card declined/i);
    await expect(errorMessage).toBeVisible();

    // Verify error state is applied to the form
    const errorState = page.getByTestId('payment-error');
    await expect(errorState).toBeVisible();

    // Verify success message does not appear
    const successMessage = page.getByText(/successfully processed/i);
    await expect(successMessage).not.toBeVisible();

    // Verify payment form is still visible
    await expect(paymentForm).toBeVisible();
  });

  test('should handle card decline with retry option', async ({ page }) => {
    // Setup: intercept the API call to simulate card decline
    await page.route('**/api/payment/process', (route) => {
      route.abort('failed');
    });

    // Intercept the API call to simulate successful payment
    await page.route('**/api/payment/process', (route) => {
      route.continue();
    });

    // Verify initial payment form is visible
    const paymentForm = page.getByRole('form', { name: /payment/i });
    await expect(paymentForm).toBeVisible();

    // Fill in card details
    const cardNumberInput = page.getByLabel(/card number/i);
    await cardNumberInput.fill('4111111111111111');

    const expiryDateInput = page.getByLabel(/expiry date/i);
    await expiryDateInput.fill('12/25');

    const cvvInput = page.getByLabel(/cvv/i);
    await cvvInput.fill('123');

    // Click the submit button
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify error message appears
    const errorMessage = page.getByText(/card declined/i);
    await expect(errorMessage).toBeVisible();

    // Verify retry button is visible
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    // Verify retry button is clickable
    await expect(retryButton).toBeEnabled();

    // Verify retry button is not disabled
    const retryButtonDisabled = page.getByRole('button', { name: /retry/i, disabled: true });
    await expect(retryButtonDisabled).not.toBeVisible();

    // Verify error state is applied to the form
    const errorState = page.getByTestId('payment-error');
    await expect(errorState).toBeVisible();

    // Verify success message does not appear
    const successMessage = page.getByText(/successfully processed/i);
    await expect(successMessage).not.toBeVisible();

    // Verify payment form is still visible
    await expect(paymentForm).toBeVisible();

    // Verify retry button is still visible
    await expect(retryButton).toBeVisible();
  });
});
